def swap_args(self, new_args, new_length=None):
        """
        This returns the same AST, with the arguments swapped out for new_args.
        """
        if new_length is None:
            new_length = len(new_args)
        if len(new_args) != new_length:
            raise ValueError("new_args must have length %d" % new_length)
        return self.copy(args=new_args)

